var chalkReplacer = function(chalk, k) {
    let total = 0n;
    for (const c of chalk) total += BigInt(c);
    let rem = BigInt(k) % total;

    for (let i = 0; i < chalk.length; ++i) {
        if (rem < BigInt(chalk[i])) return i;
        rem -= BigInt(chalk[i]);
    }
    return 0;
};
